extern "C" void action_cmd_send_player_colors_preview(lv_event_t *e) {
  (void)e;
  // Korrigiert: verwende INDEX-Variablen fǬr Modus und Farbe
  int mode        = gv_i(FLOW_GLOBAL_VARIABLE_PLAYER_COLOR_MODE_INDEX);
